Here's an example of how you could implement the dictionary lookup approach:
```python
valid_chars = {'a': True, 'b': True, 'c': True, ..., '9': True, '_': True, '-': True}

def validate_input(user_input):
    if not isinstance(user_input, str):
        return False
    if len(user_input) < 5:
        return False
    for char in user_input:
        if char not in valid_chars:
            return False
    return True
```
Alternatively, you could use a `str.translate()` method to remove invalid characters and then check the length of the resulting string:
```python
valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-')

def validate_input(user_input):
    if not isinstance(user_input, str):
        return False
    translated = ''.join(c for c in user_input if c in valid_chars)
    return len(translated) >= 5
```

